// Parses Gemini's JSON array response, strips markdown fences if present,
// and applies a fallback shorthand-nominal normalizer (50rb/50k/1jt) in case
// the model missed it. Returns one n8n item per transaction so downstream
// nodes naturally iterate over multi-transaction messages.
function normalizeNominal(raw) {
  if (typeof raw === 'number') return raw;
  if (!raw) return 0;
  const s = String(raw).toLowerCase().replace(/[^0-9a-z.,]/g, '');
  const m = s.match(/([0-9.,]+)(rb|ribu|k|jt|juta)?/);
  if (!m) return 0;
  let num = parseFloat(m[1].replace(',', '.'));
  if (m[2] === 'rb' || m[2] === 'ribu' || m[2] === 'k') num *= 1000;
  if (m[2] === 'jt' || m[2] === 'juta') num *= 1000000;
  return Math.round(num);
}

const raw = $input.first().json;
let text = raw.candidates ? raw.candidates[0].content.parts[0].text : JSON.stringify(raw);
text = text.replace(/```json|```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  return [{ json: { geminiError: true, rawText: $('IF Has Photo').first().json.message.text } }];
}
if (!Array.isArray(parsed)) parsed = [parsed];
return parsed.map(tx => ({ json: { ...tx, nominal: normalizeNominal(tx.nominal), chatId: $('IF Has Photo').first().json.message.chat.id, hasPhoto: !!($('IF Has Photo').first().json.message.photo) } }));

// Tolerance values mirrored from config/mismatch-tolerance.json - keep in sync.
const ABS_TOLERANCE = 2000;
const PCT_TOLERANCE = 0.02;
const DATE_DIFF_WARN_DAYS = 1;

const textTx = $('IF Has Photo (2)').first().json;
const visionRaw = $input.first().json;
let vision;
try {
  let t = (visionRaw.candidates ? visionRaw.candidates[0].content.parts[0].text : '{}').replace(/```json|```/g, '').trim();
  vision = JSON.parse(t);
} catch (e) {
  vision = { nominal_dari_bukti: 0, tanggal_dari_bukti: '', merchant_dari_bukti: '', metode_dari_bukti: '' };
}

const diff = Math.abs((textTx.nominal || 0) - (vision.nominal_dari_bukti || 0));
const pct = textTx.nominal ? diff / textTx.nominal : 1;
const nominalMismatch = diff > ABS_TOLERANCE && pct > PCT_TOLERANCE;

let dateDiffDays = 0;
if (textTx.tanggal && vision.tanggal_dari_bukti) {
  dateDiffDays = Math.abs((new Date(textTx.tanggal) - new Date(vision.tanggal_dari_bukti)) / 86400000);
}
const dateWarning = !nominalMismatch && dateDiffDays > DATE_DIFF_WARN_DAYS;

let status = 'ok';
if (nominalMismatch) status = 'mismatch';
else if (dateWarning) status = 'date-warning';

return [{ json: { ...textTx, vision, status, diff, dateDiffDays } }];

const text = $json.message.text.toLowerCase();
let period = 'bulan_ini';
if (text.includes('minggu')) period = 'minggu_ini';
if (text.includes('bulan lalu')) period = 'bulan_lalu';
return [{ json: { period, chatId: $json.message.chat.id } }];

const period = $('Code: Parse Period Arg').first().json.period;
const rows = $input.all().map(i => i.json);
const now = new Date();
function inPeriod(dateStr) {
  const d = new Date(dateStr);
  if (period === 'minggu_ini') { const diff = (now - d) / 86400000; return diff >= 0 && diff <= 7; }
  if (period === 'bulan_lalu') { const lm = new Date(now.getFullYear(), now.getMonth() - 1, 1); return d.getMonth() === lm.getMonth() && d.getFullYear() === lm.getFullYear(); }
  return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
}
const filtered = rows.filter(r => inPeriod(r['Tanggal Transaksi']));
const totalMasuk = filtered.filter(r => r.Jenis === 'Masuk').reduce((s, r) => s + Number(r.Nominal || 0), 0);
const totalKeluar = filtered.filter(r => r.Jenis === 'Keluar').reduce((s, r) => s + Number(r.Nominal || 0), 0);
const byKategori = {};
filtered.filter(r => r.Jenis === 'Keluar').forEach(r => { byKategori[r.Kategori] = (byKategori[r.Kategori] || 0) + Number(r.Nominal || 0); });
const topKategori = Object.entries(byKategori).sort((a, b) => b[1] - a[1]).slice(0, 5);
return [{ json: { period, totalMasuk, totalKeluar, topKategori } }];

