// '/edit <id> <field>=<value> [<field2>=<value2> ...]'
const parts = $json.message.text.trim().split(/\s+/);
const id = parts[1];
const fields = {};
parts.slice(2).forEach(p => { const [k, v] = p.split('='); if (k && v) fields[k] = v; });
return [{ json: { id, fields, hasFields: Object.keys(fields).length > 0, chatId: $json.message.chat.id } }];

// '/hutang' (list), '/hutang tambah <piutang|utang> <nama> <nominal> [jatuh_tempo YYYY-MM-DD]',
// '/hutang lunas <id>'
const parts = $json.message.text.trim().split(/\s+/);
const sub = (parts[1] || 'list').toLowerCase();
let mode = 'list';
let arah = '', nama = '', nominal = 0, jatuhTempo = '', id = '';
if (sub === 'tambah') {
  mode = 'tambah';
  arah = (parts[2] || '').toLowerCase() === 'utang' ? 'Utang' : 'Piutang';
  nama = parts[3] || '';
  nominal = parseInt((parts[4] || '0').replace(/[^0-9]/g, ''), 10) || 0;
  jatuhTempo = parts[5] || '';
} else if (sub === 'lunas') {
  mode = 'lunas';
  id = parts[2] || '';
}
return [{ json: { mode, arah, nama, nominal, jatuhTempo, id } }];

// '/goal' (list progress), '/goal tambah <nama> <target> [tanggal_target YYYY-MM-DD]'
const parts = $json.message.text.trim().split(/\s+/);
const sub = (parts[1] || 'list').toLowerCase();
let mode = 'list';
let nama = '', target = 0, tanggalTarget = '';
if (sub === 'tambah') {
  mode = 'tambah';
  nama = parts[2] || '';
  target = parseInt((parts[3] || '0').replace(/[^0-9]/g, ''), 10) || 0;
  tanggalTarget = parts[4] || '';
}
return [{ json: { mode, nama, target, tanggalTarget } }];
